#pragma once
// Tiny self-contained test framework (CONTRACTS.md section 10).
//   TEST(name) { ... }          registers a test case (name = identifier)
//   CHECK(cond)                 records a pass/fail, keeps running
//   CHECK_EQ(a, b)              equality with values printed on failure
//   CHECK_STR_EQ(a, b)          string equality (either side convertible)
// testfw::run_all() runs every registered case, prints a PASS/FAIL summary
// with counts, and returns 0 on success / 1 on any failure.
// The test binary's main() is generated by run_tests.sh and calls run_all().

#include <cstdio>
#include <sstream>
#include <string>
#include <vector>

namespace testfw {

struct Case {
  const char* name;
  void (*fn)();
};

inline std::vector<Case>& registry() {
  static std::vector<Case> r;
  return r;
}

struct Registrar {
  Registrar(const char* name, void (*fn)()) { registry().push_back({name, fn}); }
};

inline int& checks_passed() {
  static int n = 0;
  return n;
}
inline int& checks_failed() {
  static int n = 0;
  return n;
}
inline const char*& current_test() {
  static const char* n = "";
  return n;
}

inline void record_pass() { ++checks_passed(); }

inline void fail_check(const char* file, int line, const char* expr) {
  ++checks_failed();
  std::printf("    CHECK-FAIL [%s] %s:%d: %s\n", current_test(), file, line,
              expr);
}

template <typename A, typename B>
void fail_eq(const char* file, int line, const char* a_expr, const char* b_expr,
             const A& a, const B& b) {
  ++checks_failed();
  std::ostringstream sa, sb;
  sa << a;
  sb << b;
  std::printf("    CHECK-FAIL [%s] %s:%d: CHECK_EQ(%s, %s) got (%s vs %s)\n",
              current_test(), file, line, a_expr, b_expr, sa.str().c_str(),
              sb.str().c_str());
}

inline int run_all() {
  int cases_pass = 0, cases_fail = 0;
  for (const auto& c : registry()) {
    current_test() = c.name;
    const int fails_before = checks_failed();
    c.fn();
    if (checks_failed() == fails_before) {
      ++cases_pass;
      std::printf("PASS %s\n", c.name);
    } else {
      ++cases_fail;
      std::printf("FAIL %s\n", c.name);
    }
  }
  std::printf(
      "\n==== SUMMARY: %d test cases passed, %d failed; %d checks passed, "
      "%d checks failed ====\n",
      cases_pass, cases_fail, checks_passed(), checks_failed());
  return cases_fail == 0 ? 0 : 1;
}

}  // namespace testfw

#define TEST(name)                                     \
  static void test_fn_##name();                        \
  static testfw::Registrar registrar_##name(#name,     \
                                            test_fn_##name); \
  static void test_fn_##name()

#define CHECK(cond)                                                        \
  do {                                                                     \
    if (cond) {                                                            \
      testfw::record_pass();                                               \
    } else {                                                               \
      testfw::fail_check(__FILE__, __LINE__, #cond);                        \
    }                                                                      \
  } while (0)

#define CHECK_EQ(a, b)                                                     \
  do {                                                                     \
    auto _check_a = (a);                                                   \
    auto _check_b = (b);                                                   \
    if (_check_a == _check_b) {                                            \
      testfw::record_pass();                                               \
    } else {                                                               \
      testfw::fail_eq(__FILE__, __LINE__, #a, #b, _check_a, _check_b);      \
    }                                                                      \
  } while (0)

#define CHECK_STR_EQ(a, b)                                                 \
  do {                                                                     \
    const std::string _check_a = (a);                                      \
    const std::string _check_b = (b);                                      \
    if (_check_a == _check_b) {                                            \
      testfw::record_pass();                                               \
    } else {                                                               \
      testfw::fail_eq(__FILE__, __LINE__, #a, #b, _check_a, _check_b);      \
    }                                                                      \
  } while (0)
